class BrowserHistory {
    vector<string> history;
    int pos = 0;
    int end = 0;
public:
    BrowserHistory(string homepage) : history(5001) {
        history[0] = homepage;
    }

    void visit(string url) {
        ++pos;
        history[pos] = url;
        end = pos;
    }

    string back(int steps) {
        pos = max(0, pos - steps);
        return history[pos];
    }

    string forward(int steps) {
        pos = min(end, pos + steps);
        return history[pos];
    }
};
